import fs from'node:fs';import path from'node:path';import{createHash}from'node:crypto';import{performance}from'node:perf_hooks';
import{journalLines}from'../live-paper/journal-lines.mjs';import{validateUniverse}from'../live-paper/breadth.mjs';import{validatePriceObservation}from'../live-paper/market-price-publication.mjs';
import{partyTitlePairs,pairedQuotePacket}from'./paired-price-reversion-20261005.mjs';import{DEFINITION,maturedLabels,fitFrozenForecast,scoreForecast}from'../research/paired-forecast-v1.mjs';
const need=(v,c)=>{if(!v)throw Error('PAIR_FORECAST_REPLAY_'+c);};
const source=JSON.parse(fs.readFileSync('data/paired-price-reversion-results-20261005.json')).source,rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),file=path.join(rt,'market-prices.jsonl'),rawUniverse=JSON.parse(fs.readFileSync('live-paper/price-universe.json')),universe=validateUniverse(rawUniverse,rawUniverse.tournamentId),pairs=partyTitlePairs(JSON.parse(fs.readFileSync('data/markets.json')),universe),cache=new Map(),samples=pairs.map(()=>[]),lastMinutes=pairs.map(()=>-1),raw=createHash('sha256');let previous='',sequence=0;const start=performance.now();
for(const line of journalLines(file,{endByte:source.prefixBytes})){raw.update(line+'\n');const r=JSON.parse(line),{hash,...body}=r;if(r.sequence!==++sequence||r.previous!==previous||createHash('sha256').update(JSON.stringify(body)).digest('hex')!==hash)throw Error('SOURCE_CHAIN');previous=hash;const s=validatePriceObservation(r.event.snapshot,universe),at=Date.parse(s.receivedAt),requestStartedAt=Date.parse(s.requestStartedAt),changed=new Set();for(const id of s.missingIds)cache.delete(id);for(const q of s.quotes){cache.set(q.exchangeId,{...q,requestStartedAt,receivedAt:at});changed.add(q.exchangeId);}const minute=Math.floor(at/60000);
 for(let i=0;i<pairs.length;i++){if(lastMinutes[i]===minute||!pairs[i].legs.some(l=>changed.has(l.exchangeId)))continue;const p=pairedQuotePacket(pairs[i],cache,at);if(p){samples[i].push({pair:i,at,buy:Number(p.buy)/1e6,sell:Number(p.sell)/1e6,minRequestAt:Math.min(...p.requests)});lastMinutes[i]=minute;}}
}
need(raw.digest('hex')===source.sha256&&sequence===source.records&&previous===source.tailHash,'SOURCE_BINDING');const cutoff=Math.floor(Date.parse(source.first)+DEFINITION.trainingFraction*(Date.parse(source.last)-Date.parse(source.first))),results=[];
for(const horizonMs of DEFINITION.horizonsMs){const labels=samples.flatMap(r=>maturedLabels(r,horizonMs)),model=fitFrozenForecast(labels,cutoff);results.push({horizonMs,model,score:scoreForecast(model,labels),censoredSamples:samples.reduce((n,r)=>n+r.length,0)-labels.length});}
const out={schemaVersion:1,at:new Date().toISOString(),mode:'frozen_pooled_liquidation_change_diagnostics',source,cutoff:new Date(cutoff).toISOString(),definition:DEFINITION,pairs:pairs.length,samples:samples.reduce((n,r)=>n+r.length,0),wallMs:performance.now()-start,results,allAttemptsRetained:true,networkRequests:0,competitionOrders:0,simulatedFills:0,profitabilityEstablished:false,limitations:['Quote labels lack executable depth and are not actual trades or funded returns.','Contemporary title discovery does not backfill historical exact predicate knowledge.','Labels crossing the training cutoff are excluded from fitting; later feature scaling is frozen.','Overlapping horizons and correlated election/pair observations are not independent samples; UTC-day results are exposed without iid confidence claims.','Three horizons and ridge strength were fixed before fitting; no best-of-history production winner is selected.','The same original source prefix is development data; only the chronological later segment is model-held-out, not untouched by all prior research.']};
const output='data/paired-forecast-results-20261005-v1.json';fs.writeFileSync(output,JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({samples:out.samples,wallMs:out.wallMs,cutoff:out.cutoff,results:results.map(r=>({horizonMs:r.horizonMs,train:r.model.trainingRows,...r.score})),profitabilityEstablished:false}));
